import React, { useState, useEffect } from 'react';
import { apiUpdateProfile, setCurrentUser, getCurrentUser } from '../services/api';
import './EditProfileModal.css';

interface EditProfileModalProps {
  onClose: () => void;
  onSaved: (updatedUser: any) => void;
}

const EditProfileModal: React.FC<EditProfileModalProps> = ({ onClose, onSaved }) => {
  const currentUser = getCurrentUser();
  const [displayName, setDisplayName] = useState(currentUser?.displayName || '');
  const [avatarUrl, setAvatarUrl] = useState(currentUser?.avatarUrl || '');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [imgError, setImgError] = useState(false);

  const fallbackAvatar = `https://api.dicebear.com/7.x/thumbs/svg?seed=${currentUser?.username}`;
  const previewSrc = avatarUrl.trim() || fallbackAvatar;

  useEffect(() => { setImgError(false); }, [avatarUrl]);

  const handleSave = async () => {
    setSaving(true);
    setError('');
    try {
      const { user } = await apiUpdateProfile({ displayName, avatarUrl });
      setCurrentUser(user);
      onSaved(user);
      onClose();
    } catch (err: any) {
      setError(err.message || 'Failed to save changes');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="ep-overlay" onClick={onClose}>
      <div className="ep-card" onClick={e => e.stopPropagation()}>
        <div className="ep-header">
          <h2 className="ep-title">Edit Profile</h2>
          <button className="ep-close" onClick={onClose} aria-label="Close">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
              <line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/>
            </svg>
          </button>
        </div>

        {/* Avatar preview */}
        <div className="ep-avatar-wrap">
          <img
            className="ep-avatar-preview"
            src={imgError ? fallbackAvatar : previewSrc}
            alt="Avatar preview"
            onError={() => setImgError(true)}
          />
          <div className="ep-avatar-ring" />
        </div>

        <div className="ep-fields">
          <div className="ep-field">
            <label className="ep-label">Display Name</label>
            <input
              className="ep-input"
              type="text"
              placeholder="Your name"
              value={displayName}
              onChange={e => setDisplayName(e.target.value)}
              maxLength={40}
            />
          </div>

          <div className="ep-field">
            <label className="ep-label">Avatar URL</label>
            <input
              className="ep-input"
              type="url"
              placeholder="https://example.com/avatar.png"
              value={avatarUrl}
              onChange={e => setAvatarUrl(e.target.value)}
            />
            <span className="ep-hint">Leave blank to use your default avatar</span>
          </div>
        </div>

        {error && <p className="ep-error">{error}</p>}

        <div className="ep-actions">
          <button className="ep-btn ep-btn--cancel" onClick={onClose} disabled={saving}>
            Cancel
          </button>
          <button className="ep-btn ep-btn--save" onClick={handleSave} disabled={saving}>
            {saving ? 'Saving…' : 'Save Changes'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default EditProfileModal;
